1	export type Item = {
2	  type: string;
3	};
4	
5	export type QuoteStep = {
6	  op: "quote";
7	  items: Item[];
8	};
9	
10	export type Scenario = {
11	  customer: { yearsWithMHPCO: number };
12	  steps: QuoteStep[];
13	};
14	
15	export type ScenarioResult = {
16	  results: unknown[];
17	};
18	
19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	};
29	
30	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
31	
32	const BLOCK_SIZE = 3;
33	const BLOCK_BASE_PREMIUM = 60;
34	
35	const isBlockOfAlikeItems = (items: Item[]): boolean =>
36	  items.length === BLOCK_SIZE &&
37	  items.every((item) => item.type === items[0].type);
38	
39	const totalBasePremiumOf = (items: Item[]): number =>
40	  isBlockOfAlikeItems(items)
41	    ? BLOCK_BASE_PREMIUM
42	    : items.reduce((total, item) => total + basePremiumOf(item), 0);
43	
44	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
45	
46	const quotePremium = (items: Item[]): number => {
47	  const basePremium = totalBasePremiumOf(items);
48	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
49	
50	  return roundedInMHPCOsFavour(
51	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
52	  );
53	};
54	
55	export const runScenario = (scenario: Scenario): ScenarioResult => ({
56	  results: scenario.steps.map((step) => ({
57	    premium: quotePremium(step.items),
58	  })),
59	});
